/* Ellingson Plumbing confirmation scenes (v4 ink). Tiny loader + player.
 * Scene drawings live in /scenes/<key>.js and are fetched only when a scene plays (after submit, thanks page, dev gallery).
 * Registry: per pricebook service option (OPTION_SCENES), then per JOBS id (JOB_SCENES), then "other".
 * Generated by assets/ink/scenes4.py; edit the generator, not the data files. */
(function () {
  var cur = document.currentScript && document.currentScript.src;
  var BASE = cur ? cur.replace(/scenes\.js(\?.*)?$/, "") : "/";
  var VER = "4";
  var TITLES = {"shutoff": "Water shut off, leak stopped", "burst": "Burst pipe repaired", "freezethaw": "Frozen line thawed and repaired", "diagnose": "Leak found and diagnosed", "clog": "Toilet unclogged", "mainline": "Main line cleared", "hydrojet": "Line hydro-jetted", "cleanout": "Cleanout installed", "cammain": "Main line camera inspected", "cambranch": "Branch line camera inspected", "tankswap": "Water heater replaced", "tankcode": "Water heater brought to code", "flush": "Water heater flushed", "nohot": "T and P valve, anode, or element service", "tankless": "Tankless water heater installed", "sumpswap": "Sump pump replaced", "battery": "Battery backup sump installed", "checkvalve": "Check valve replaced", "sumptest": "Sump pump tested and serviced", "thaw": "Frozen pipes thawed", "frozenburst": "Frozen and burst pipe repaired", "slab": "Slab leak located", "softservice": "Water softener serviced", "softinstall": "Water softener installed", "ironro": "Iron filter or RO installed", "remodel": "Remodel plumbing roughed in", "commercial": "Backflow device tested", "other": "Plumber on the way", "toilet": "Toilet installed", "sink": "Faucet or sink installed", "shower": "Shower valve installed", "tub": "Tub installed", "disposal": "Garbage disposal installed", "cartridge": "Faucet cartridge replaced"};
  var OPTION_SCENES = {
    "Emergency repair": ["shutoff", "burst", "freezethaw", "diagnose"],
    "Drain / sewer": ["clog", "mainline", "hydrojet", "cleanout", "cammain", "cambranch"],
    "Water heater": ["tankswap", "tankcode", "flush", "nohot", "tankless"],
    "Sump pump / flooding": ["sumpswap", "battery", "checkvalve", "sumptest"],
    "Frozen or burst pipe": ["thaw", "frozenburst", "slab"],
    "Softener / filtration": ["softservice", "softinstall", "ironro"],
    "Remodel / rough-in": ["remodel"],
    Commercial: ["commercial"],
    "Something else": ["other"],
    "Fixture install": ["toilet", "sink", "shower", "tub", "disposal", "cartridge"]
  };
  var JOB_SCENES = { burst: "burst", leak: "shutoff", clog: "clog", backup: "mainline", frozen: "thaw", nohot: "nohot", heater: "tankswap", sump: "sumpswap", softener: "softservice", other: "other", toilet: "toilet", sink: "sink", shower: "shower", tub: "tub" };
  var FPS = 12, BOIL = 8, uid = 0;
  function rm() { return !!(window.matchMedia && matchMedia("(prefers-reduced-motion: reduce)").matches); }
  function resolve(ctx) {
    ctx = ctx || {};
    if (ctx.scene && TITLES[ctx.scene]) return ctx.scene;
    var byOpt = OPTION_SCENES[ctx.service] && OPTION_SCENES[ctx.service][Number(ctx.optionIndex) || 0];
    if (byOpt && TITLES[byOpt]) return byOpt;
    var byJob = JOB_SCENES[ctx.job];
    if (byJob && TITLES[byJob]) return byJob;
    return "other";
  }
  var pending = {};
  function load(key) {
    var D = (window.EESceneData = window.EESceneData || {});
    if (D[key]) return Promise.resolve(D[key]);
    if (!pending[key]) pending[key] = new Promise(function (res, rej) {
      var s = document.createElement("script");
      s.src = BASE + "scenes/" + key + ".js?v=" + VER; s.async = true;
      s.onload = function () { D[key] ? res(D[key]) : rej(new Error("scene " + key)); };
      s.onerror = function () { delete pending[key]; rej(new Error("scene " + key)); };
      document.head.appendChild(s);
    });
    return pending[key];
  }
  function stop(host) { if (host && host._eeStop) host._eeStop(); }
  /* play(host, key[, {frame:n|"mid"}]) -> Promise that resolves when the scene ends (immediately under reduced motion). */
  function play(host, key, opt) {
    opt = opt || {}; stop(host);
    key = TITLES[key] ? key : "other";
    host.classList.add("scene-loading");
    return load(key).then(function (d) {
      host.classList.remove("scene-loading");
      var p = "ees" + (++uid) + "-", defs = "", i;
      for (i = 0; i < d.f.length; i++) defs += '<g id="' + p + i + '">' + d.f[i] + "</g>";
      var bg = "";
      for (i = 0; i < d.bg.length; i++) bg += '<g class="bgv"' + (i ? ' style="display:none"' : "") + ">" + d.bg[i] + "</g>";
      host.querySelectorAll("svg").forEach(function (n) { n.remove(); });
      host.insertAdjacentHTML("afterbegin", '<svg viewBox="' + d.vb + '" preserveAspectRatio="xMidYMid meet" role="img" aria-label="' + d.alt.replace(/"/g, "&quot;") +
        '" style="color:#0B0F0D"><defs>' + defs + "</defs>" + bg + '<g class="fr"></g></svg>');
      var svg = host.querySelector("svg"), fr = svg.querySelector(".fr"), bgs = svg.querySelectorAll(".bgv"), last = -1, lb = 0;
      function show(n) {
        if (n === last) return; last = n;
        fr.innerHTML = d.s[n].map(function (k) { return '<use href="#' + p + k + '"/>'; }).join("");
      }
      function boil(v) { if (v === lb) return; bgs[lb].style.display = "none"; bgs[v].style.display = ""; lb = v; }
      var N = d.s.length;
      if (opt.frame != null) { show(opt.frame === "mid" ? Math.floor(N * 0.42) : Math.min(N - 1, +opt.frame)); return; }
      if (rm()) { show(N - 1); return; }
      return new Promise(function (res) {
        var t0 = performance.now(), raf, done = false;
        function tick(now) {
          var e = now - t0, n = Math.floor(e * FPS / 1000);
          boil(Math.floor(e * BOIL / 1000) % bgs.length);
          if (n < N) show(n); else { show(N - 1); if (!done) { done = true; res(); } }
          if (e < N * 1000 / FPS + 2500) raf = requestAnimationFrame(tick); else boil(0);
        }
        host._eeStop = function () { cancelAnimationFrame(raf); if (!done) { done = true; res(); } };
        raf = requestAnimationFrame(tick);
      });
    }).catch(function () { host.classList.remove("scene-loading"); });
  }
  function list() { return Object.keys(TITLES).map(function (k) { return { key: k, label: TITLES[k] }; }); }
  window.EEScenes = { resolve: resolve, play: play, load: load, list: list, OPTION_SCENES: OPTION_SCENES, JOB_SCENES: JOB_SCENES };
})();
